import {ENVOY,VOYAGE_STAGES,REVIEW,FINAL_QUIZ,activeVoyage,activeFinale,prepareVoyage,boardVoyage,createVoyageRuntime,stepVoyage,retryVoyage,confirmDiplomacy,reviewRecord,answerFinal,completeEnding} from './voyage.js?v=56';
import {drawVoyage,voyageImage} from './voyage-render.js?v=56';
const art=(id,alt,cls='')=>`<img class="${cls}" src="${new URL('./assets/voyage/'+id+'.svg?v=56',import.meta.url).href}" alt="${alt}">`;
export function createVoyageUI(api){
 const {$,state,panel,close,save,hud,toast,finishEvent,avatarSource,imageTag}=api;let rt=null,identity=null,serial=0,axis=new Set(),cutDone=null;
 const s=()=>state(),v=()=>s().ancient.voyage,commit=()=>{save();hud();};
 function cancel(){rt=null;axis.clear();cutDone=null;serial++;}
 function show(title,html,options={}){panel(title,html,options);const stamp=serial;return fn=>(...args)=>{if(stamp===serial)fn(...args);};}
 function permitted(){return activeVoyage(s())||activeFinale(s());}
 function entry(){if(!permitted()){panel('한강의 사신단','<p>지금의 이야기 임무를 먼저 이어가 보자.</p>');return;}
 if(s().ancient.home.commerce.cart.active){panel('먼저 운송을 마치자','<p>수레 운송 중이야. 지금의 짐을 납품한 뒤 다시 찾아오렴. 운송 기록은 그대로 있어.</p>');return;}
 if(s().progress.ancient===27){records();return;}
 if(v().success){arrival();return;}
 if(v().boarded){sail();return;}
 const country=s().ancient.country,view={baekje:'우리 백제가 다른 나라와 뜻을 나누는 바닷길을 함께 살펴보자.',goguryeo:'고구려에서 온 여행자로서 백제의 외교를 살펴보자. 백제의 관리가 되는 것은 아니야.',silla:'경주 주변에서 온 여행자로서 여러 나라가 관계를 맺는 모습을 살펴보자.'}[country];
 const bind=show('시간이 흘러 · 372년',`${art('document','외교 문서','voyage-exhibit-image')}<p>백제는 중국 동진에 사신을 보냈어.<br>${view}</p><p>문서와 식량, 교류할 물품은 준비됐어. 함께 항해를 도와줄래?</p><p class="voyage-note">한강에서 바다와 항구로 이어지는 여행을 압축한 창작 체험이야. 실제 372년의 배·사신 구성·항로를 복원한 장면은 아니야.</p><button id="voyage-prep" class="primary full">출항 준비 확인</button>`);
 $('#voyage-prep').onclick=bind(()=>{if(!prepareVoyage(s()))return;commit();preparation();});
 }
 function preparation(){if(!activeVoyage(s()))return;const bind=show('사신단 · 출항 준비',`<div class="voyage-prep">${art('document','동진에 전할 문서')}<p><b>외교 문서</b><br>나라의 뜻을 전해.<br><b>식량</b><br>긴 여행 중에 먹어.<br><b>교류할 물품</b><br>다른 나라와 관계를 나누는 데 써.</p></div><p>← → 또는 A/D로 목선을 조종해 장애물을 피하자.<br>태블릿은 아래의 방향 버튼을 누르고 있으면 돼.</p><p class="voyage-note">생활 아이템·엽전·수레는 소비하지 않아. 3구간, 총 80초 항해야. 배가 손상되면 현재 구간부터 다시 도전할 수 있어.</p><button id="voyage-board" class="primary full">사신과 함께 배에 오르기</button>`);
 $('#voyage-board').onclick=bind(()=>{if(!activeVoyage(s())||!v().prepared)return;shell('boarding');cutDone=()=>{if(!boardVoyage(s()))return;commit();sail();};});}
 function shell(scene){const bind=show('바다를 건너는 사신단',`<div class="voyage-shell"><div class="voyage-header"><div><h3 id="voyage-stage">출항하는 사신단</h3><p id="voyage-time">372년 · 창작 항해 체험</p></div><span id="voyage-hull" class="voyage-hull" aria-live="polite"></span><button id="voyage-pause">일시정지</button></div><div class="voyage-progress"><span id="voyage-progress"></span></div><div class="voyage-view"><canvas id="voyage-canvas" width="1000" height="700" role="img" aria-label="사신과 내가 탑승한 고대 목선, 바다와 암초·표류목"></canvas><div id="voyage-message" class="voyage-interlude" hidden></div></div><div class="voyage-controls"><button id="voyage-left" aria-label="배를 왼쪽으로 조종">◀</button><p class="voyage-tip" id="voyage-tip">방향 버튼을 누르고 있으면 이동해. 손을 떼면 멈춰.</p><button id="voyage-right" aria-label="배를 오른쪽으로 조종">▶</button></div></div>`,{wide:true,closable:false,type:'voyage'});
 identity=s();rt=scene?{scene,stage:scene==='arrival'?2:0,elapsed:0,x:500}:createVoyageRuntime(s());
 for(const [id,key]of [['left','left'],['right','right']]){const button=$('#voyage-'+id);button.disabled=Boolean(scene);button.onpointerdown=bind(e=>{e.preventDefault();if(rt?.status!=='sailing'||rt.paused)return;button.setPointerCapture?.(e.pointerId);axis.add(key);});for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,()=>axis.delete(key));}
 $('#voyage-pause').onclick=bind(pause);
 return rt;
 }
 function sail(){if(!activeVoyage(s())||!v().boarded)return;const runtime=shell();if(runtime.status==='failed')message('배를 수리하자','이번 구간의 출발 지점에서 내구도 3칸으로 다시 도전할 수 있어. 재산은 잃지 않아.','현재 구간 다시 도전',()=>{if(retryVoyage(s(),runtime)){commit();sail();}});}
 function message(title,text,button,action){if(!rt)return;axis.clear();const current=rt,stamp=serial,el=$('#voyage-message');el.hidden=false;el.innerHTML=`<div class="voyage-message"><h3>${title}</h3><p>${text}</p><button id="voyage-action" class="primary">${button}</button><button id="voyage-leave">한강 나루에서 나중에 이어하기</button></div>`;$('#voyage-action').onclick=()=>{if(rt!==current||stamp!==serial||!activeVoyage(s()))return;action();};$('#voyage-leave').onclick=()=>{if(stamp!==serial)return;commit();close();toast('사신단 담당자를 만나면 현재 구간부터 이어져.');};}
 function pause(){if(!rt||rt.scene){if(rt?.scene){commit();close();}return;}if(rt.status!=='sailing')return;rt.paused=true;axis.clear();message('항해 일시정지','현재 구간 진행을 잠시 멈췄어. 나가면 이 구간의 출발 지점부터 이어져.','항해 계속하기',()=>{rt.paused=false;$('#voyage-message').hidden=true;});}
 function arrival(){if(!activeVoyage(s())||!v().success)return;shell('arrival');cutDone=diplomacy;}
 function diplomacy(){if(!activeVoyage(s())||!v().success)return;const bind=show('372년 · 동진과의 외교',`${art('document','나라의 뜻을 전하는 문서','voyage-exhibit-image')}<p>무사히 도착했어! 이제 백제의 뜻을 전할 수 있겠군.</p><p><b>372년, 백제는 중국 동진과 공식 외교 관계를 맺었어.</b><br>나라끼리 뜻을 전하고 관계를 맺는 외교는 물건을 사고파는 교역과는 달라.</p><p class="voyage-note">이 항구와 항해 중의 사건은 게임용 창작이야.</p><button id="voyage-finish" class="primary full">동진 외교 기록 · 40엽전 / 평판 +3 / 경험치 12</button>`);
 $('#voyage-finish').onclick=bind(()=>{if(!confirmDiplomacy(s()))return;close();finishEvent('ancient:4c-voyage');records();});}
 function records(force=false){if(!activeFinale(s()))return;if(v().quiz===2){ending();return;}if(!force&&v().review.length===4&&v().quiz>0){quiz();return;}
 const bind=show('QUEST 7 · 근초고왕의 시대',`<p>한강의 첫 거래부터 바다를 건너기까지, 네 가지 기록을 함께 정리하자.</p><div class="voyage-review-grid">${REVIEW.map(r=>`<button data-voyage-record="${r.id}">${r.art==='king'?imageTag('kingGeunchogo','근초고왕'):r.art==='cargo'?imageTag('storyCargo','교역 물품'):art(r.art,r.title)}<span><b>${r.title} ${v().review.includes(r.id)?'✓':''}</b><br><small>${r.time}</small></span></button>`).join('')}</div><div id="voyage-record-detail" class="voyage-record-detail">그림의 기록을 골라 살펴보자.</div><div class="voyage-timeline"><span>한강을 중심으로 성장</span><span>남쪽으로 영향력 확대</span><span>369 치양 → 371 평양성</span><span>372 동진 외교</span></div><button id="voyage-to-quiz" class="primary full" ${v().review.length===4?'':'disabled'}>마지막 확인 문제 2개</button>`,{wide:true});
 document.querySelectorAll('[data-voyage-record]').forEach(el=>el.onclick=bind(()=>{const r=REVIEW.find(r=>r.id===el.dataset.voyageRecord);if(!reviewRecord(s(),r.id))return;commit();$('#voyage-record-detail').textContent=r.text;el.querySelector('b').textContent=r.title+' ✓';$('#voyage-to-quiz').disabled=v().review.length!==4;}));$('#voyage-to-quiz').onclick=bind(()=>{if(activeFinale(s())&&v().review.length===4)quiz();});}
 function quiz(){if(!activeFinale(s())||v().review.length!==4)return;if(v().quiz===2){ending();return;}const index=v().quiz,q=FINAL_QUIZ[index],bind=show('4세기 역사 확인 · '+(index+1)+'/2',`<h3>${q.question}</h3>${q.options.map((a,i)=>`<button class="voyage-choice" data-final-answer="${i}">${i+1}. ${a}</button>`).join('')}<p id="final-feedback" aria-live="polite">틀려도 다시 고를 수 있어. 재산은 잃지 않아.</p><button id="final-review" class="full">기록 다시 살펴보기</button>`);
 document.querySelectorAll('[data-final-answer]').forEach(el=>el.onclick=bind(()=>{if(!activeFinale(s())||v().quiz!==index)return;if(!answerFinal(s(),index,Number(el.dataset.finalAnswer))){$('#final-feedback').textContent=q.hint;return;}commit();quiz();}));$('#final-review').onclick=bind(()=>records(true));}
 function ending(step=0){if(!activeFinale(s())||v().quiz!==2)return;const lines=['한강을 중심으로 백제는 크게 성장했어.','남쪽으로 영향력을 넓히고 고구려와 경쟁했지.','중국 동진과도 외교 관계를 맺었어. 앞으로 삼국의 힘은 또 달라질 거야.'];const bind=show('근초고왕의 시대 · 제1장 마무리',`<div class="voyage-court">${imageTag('kingGeunchogo','근초고왕 전용 SD 캐릭터','ending-king')}${art('boat','한강을 오가는 목선','ending-boat')}${art('plaque','한강 교역 기록판','ending-plaque')}</div><p class="voyage-quote">${lines[step]}</p><p class="voyage-note">근초고왕의 말은 게임용 창작 대사야. 한강 교역 기록판도 실제 유물이 아닌 기념 전시물이야.</p><button id="final-ending-next" class="primary full">${step<2?'이야기 계속':'4세기 백제편 완료 · 45엽전 / 평판 +5 / 경험치 12'}</button>`,{wide:true});
 $('#final-ending-next').onclick=bind(()=>{if(!activeFinale(s())||v().quiz!==2)return;if(step<2){ending(step+1);return;}if(!completeEnding(s()))return;close();finishEvent('ancient:4c-finale');panel('제1장 완료 · 한강에서 바다까지',`${art('plaque','획득한 한강 교역 기록판','voyage-exhibit-image')}<p><b>4세기 백제편을 모두 마쳤어!</b><br>한강 교역 기록판을 얻었어. 내 집의 전시 공간에서 골라 놓을 수 있어.</p><p>다음은 5세기 고구려가 성장하는 이야기야.<br>다음 이야기가 열릴 때까지 지금의 마을과 집에서 자유롭게 지내자.</p><p class="voyage-note">현재 시기는 4세기로 유지돼. 5세기는 아직 시작되지 않아.</p>`);});}
 function tick(dt){if(!rt)return;if(identity!==s()||api.screen()!=='voyage'||!activeVoyage(s())){cancel();return;}const canvas=$('#voyage-canvas');if(!canvas){cancel();return;}
 if(rt.scene){rt.elapsed+=Math.max(0,Math.min(dt,.25));drawVoyage(canvas,s(),rt,avatarSource);if(rt.elapsed>=3.8){const fn=cutDone;cutDone=null;fn?.();}return;}
 const result=stepVoyage(s(),rt,dt,(axis.has('right')?1:0)-(axis.has('left')?1:0));drawVoyage(canvas,s(),rt,avatarSource);
 const profile=VOYAGE_STAGES[Math.min(rt.stage,2)];$('#voyage-stage').textContent=(Math.min(rt.stage+1,3))+'구간 · '+profile.name;$('#voyage-time').textContent=Math.min(profile.seconds,Math.floor(rt.elapsed))+' / '+profile.seconds+'초 · 전체 80초';$('#voyage-hull').textContent='배 내구도 '+'♥'.repeat(v().hull)+'♡'.repeat(3-v().hull);$('#voyage-progress').style.width=(Math.min(1,rt.elapsed/profile.seconds)*100)+'%';$('#voyage-tip').textContent=rt.stage===2?'물살이 배를 살짝 밀어. 좌우로 방향을 보정하자.':v().failures[rt.stage]>=3?'도움 모드 · 장애물이 느려지고 통로가 넓어졌어.':'암초와 표류목을 피해 배를 조종하자.';
 if(result){commit();if(result==='failed'){const current=rt;message('배가 손상됐어','선원들과 안전하게 배를 수리하자. 지금 구간부터 내구도 3칸으로 다시 도전해.','현재 구간 다시 도전',()=>{if(retryVoyage(s(),current)){commit();sail();}});}else if(result==='checkpoint')message('이 구간을 통과했어!','다음 구간의 출발 지점을 기록했어. 나중에 이어해도 앞 구간을 다시 하지 않아.','다음 구간 출항',sail);else if(result==='arrived')arrival();}
 }
 function key(e,down){if(api.screen()!=='voyage'||!rt)return false;const key={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'}[e.key];if(key){e.preventDefault();if(down&&rt.status==='sailing'&&!rt.paused&&!rt.scene)axis.add(key);else axis.delete(key);return true;}if(e.key==='Escape'){e.preventDefault();if(down&&!e.repeat)pause();return true;}return true;}
 addEventListener('blur',()=>axis.clear());document.addEventListener('visibilitychange',()=>{axis.clear();if(document.hidden&&rt?.status==='sailing'&&!rt.paused)pause();});
 ['boat','reef','log','document','plaque'].forEach(voyageImage);
 return {interact:e=>{if(e.type!=='voyageStory')return false;if(Math.hypot(s().x-e.x,s().y-e.y)<1.65)entry();return true;},entry,tick,key,cancel,runtime:()=>rt,prepareQA:()=>cancel()};
}
